package goguitarpro
import ("reflect"; "testing")

func TestReviewChordAnnularConsumer(t *testing.T) {
 song := semanticValidPitchedGP8Song(t)
 song.Tracks[0].Settings.Notation = true
 firstFret:=uint8(3)
 song.Tracks[0].Measures[0].Voices[0].Beats[0].Effect.Chord=&Chord{
  Name:"Audit chord", FirstFret:&firstFret, Length:7,
  Strings:[]int8{3,3,-1,0,5,5,7},
  Barres:[]Barre{{Fret:3,Start:1,End:2},{Fret:5,Start:5,End:6}},
  Fingerings:[]Fingering{FingeringIndex,FingeringIndex,FingeringOpen,FingeringOpen,FingeringAnnular,FingeringAnnular,FingeringThumb},
 }
 data, report, err := ExportWithReport(song, ExportFormatGP8, ExportOptions{LossPolicy:ExportLossPolicy{RequirePreservation:true}})
 if err != nil { t.Fatalf("export failed: %v; %#v",err,report.Entries) }
 var facts []conformanceAlphaTabChordDiagramFact
 readAlphaTabOracleFacts(t,"--chord-diagrams",writeConformanceFixture(t,data),&facts)
 t.Logf("strict export reports=%#v; consumer facts=%#v",report.Entries,facts)
 for _,f:=range facts { if f.Name=="Audit chord" { if !reflect.DeepEqual(f.BarreFrets,[]int{3,5}) {t.Fatalf("barre frets=%v, want [3 5]",f.BarreFrets)}; return } }
 t.Fatal("chord disappeared")
}

package goguitarpro
import "testing"

func TestReviewLegatoExcerptConsumer(t *testing.T) {
 song := semanticValidPitchedGP8Song(t)
 song.Tracks[0].Settings.Notation = true
 song.Tracks[0].Measures[0].Voices[0].Beats[0].Legato = &BeatLegato{Destination: true}
 data, report, err := ExportWithReport(song, ExportFormatGP8, ExportOptions{LossPolicy: ExportLossPolicy{RequirePreservation:true}})
 if err != nil { t.Fatal(err) }
 var facts []conformanceLegatoFact
 readAlphaTabOracleFacts(t, "--legato", writeConformanceFixture(t,data), &facts)
 t.Logf("strict export reports=%#v; consumer facts=%#v",report.Entries,facts)
 if len(facts)==0 || !facts[0].Destination { t.Fatal("authored destination-only endpoint disappeared in pinned consumer") }
}
